    public Transform PControllerObj;
    public PlayerController PControllerScript;
    public Transform TControllerObj;
    public TrainController TControllerScript;
    public Transform ItemSpawnerObj;
    public ItemSpawner ItemSpawnerScript;
    public void Awake()
    {
        PControllerScript = PControllerObj.GetComponent<PlayerController>();
        TControllerScript = TControllerObj.GetComponent<TrainController>();
        theDeLorean = GameObject.FindWithTag("DeLorean");
    }
    public void Start()
    {
        grid = new GameObject[gridWidth, gridHeight];
        for (var i = 0; i < gridWidth; i++)
        {
            for (var j = 0; j < gridHeight; j++)
            {
                var tileValue = multiDimensionalArray[i][j];
                if (tileValue == 0)
                {
                    grid[i,j] = borderTile;
                    Instantiate (grid[i,j], new Vector3(i, j, 0), Quaternion.identity);
                }
                else if (tileValue == 1)
                {
                    grid[i,j] = grassTile;
                    Instantiate (grid[i,j], new Vector3(i, j, 0), Quaternion.identity);
                }
                else if (tileValue == 2)
                {
                    grid[i,j] = buildingTile;
                    Instantiate (grid[i,j], new Vector3(i, j, 0), Quaternion.identity);
                }
                else if (tileValue == 3)
                {
                    grid[i,j] = hazardSpawnerTile;
                    Instantiate (grid[i,j], new Vector3(i, j, 0), Quaternion.identity);
                }
                else if (tileValue == 4)
                {
                    grid[i,j] = vehicleSpawnerTile;
                    Instantiate (grid[i,j], new Vector3(i, j, 0), Quaternion.identity);
                }
                else if (tileValue == 5)
                {
                    grid[i,j] = enemySpawnerTile;
                    Instantiate (grid[i,j], new Vector3(i, j, 0), Quaternion.identity);
                }
                else if (tileValue == 6)
                {
                    grid[i,j] = itemSpawnerTile;
                    Instantiate (grid[i,j], new Vector3(i, j, 0), Quaternion.identity);
                }
                else if (tileValue == 7)
                {
                    grid[i,j] = railRoadTile;
                    Instantiate (grid[i,j], new Vector3(i, j, 0), Quaternion.identity);
                    TControllerScript.trainArr.Add (new Vector3(i, j, -0.01f));
                }
                else if (tileValue == 8)
                {
                    grid[i,j] = inBoundRailTile;
                    Instantiate (grid[i,j], new Vector3(i, j, 0), Quaternion.identity);
                }
                else if (tileValue == 9)
                {
                    grid[i,j] = roadTile;
                    Instantiate (grid[i,j], new Vector3(i, j, 0), Quaternion.identity);
                }
            }
        }
    }
    public void Update()
    {
        gameTimer = gameTimer + Time.fixedDeltaTime;
        if (PControllerScript.DControllerScript.winCondition)
        {
            LoadScene (2);
        }
        if (PControllerScript.DControllerScript.eighty8MphScript.backInTime)
        {
            PControllerScript.DControllerScript.inVehicle = false;
            PControllerScript.canMove = true;
        }
        if (PControllerScript.trainSwitched)
        {
        }
        if (isMartyMoving)
        {
            var step = PControllerScript.speed * Time.deltaTime;
            PControllerScript.transform.position = Vector3.MoveTowards(PControllerScript.transform.position, touchPos, step);
            Debug.Log("<> ------------- <> IS MARTY McFLY LERPING DONE?!?!?!");
            if (PControllerScript.transform.position == (Vector3)touchPos)
            {
                isMartyMoving = false;
            }
        }
        else if (isDeLoreanMoving)
        {
            var Dstep = PControllerScript.DControllerScript.speed * Time.deltaTime;
            PControllerScript.DControllerScript.transform.position = Vector3.MoveTowards(PControllerScript.DControllerScript.transform.position, touchPos, Dstep);
            if (touchPos.y > 0)
            PControllerScript.DControllerScript.sRenderer.sprite = PControllerScript.DControllerScript.spriteUp;
            else if (touchPos.y < 0)
            PControllerScript.DControllerScript.sRenderer.sprite = PControllerScript.DControllerScript.spriteDown;
            else if (touchPos.x > 0)
            PControllerScript.DControllerScript.sRenderer.sprite = PControllerScript.DControllerScript.spriteRight;
            else if (touchPos.x < 0)
            PControllerScript.DControllerScript.sRenderer.sprite = PControllerScript.DControllerScript.spriteLeft;
            Debug.Log("<> ------------- <> IS DELOREAN LERPING DONE?!?!?!");
            if (PControllerScript.DControllerScript.transform.position == (Vector3)touchPos)
            {
                isDeLoreanMoving = false;
            }
        }
        if (Input.touchCount > 0 && Input.GetTouch(0).phase == TouchPhase.Ended)
        {
            Touch touch = Input.GetTouch(0);
            Debug.Log ("number of fingers : " + Input.touchCount);
            RaycastHit hit;
            Ray ray = Camera.main.ScreenPointToRay(Input.GetTouch(0).position);
            if (Physics.Raycast(ray, out hit))
            {
                Collider coll = hit.collider;
                if ((coll.name == "testDeLorean" | coll.name == "testDeloreanSprite") && PControllerScript.canMove)
                {
                    Handheld.Vibrate();
                    PControllerScript.MeasureDistance();
                    if (PControllerScript.distanceBetweenD <= 3.00f)
                    {
                        Debug.Log("INSIDE DELOREAN");
                        PControllerScript.DControllerScript.inVehicle = true;
                    }
                    else if (PControllerScript.distanceBetweenC <= 3.00f)
                    {
                        Debug.Log("INSIDE C-TRUCK");
                        PControllerScript.CTruckControllerScript.inVehicle = true;
                    }
                    else if (PControllerScript.distanceBetweenM <= 2.00f)
                    {
                        Debug.Log("INSIDE M-TRUCK");
                        PControllerScript.MTruckControllerScript.inVehicle = true;
                    }
                }
                else if (coll.name == "testCTruck" && PControllerScript.canMove)
                {
                    Handheld.Vibrate();
                }
                else if (coll.name == "testMTruck" && PControllerScript.canMove)
                {
                    Handheld.Vibrate();
                }
                else if ((coll.name == "testDeLorean" | coll.name == "testDeloreanSprite") && PControllerScript.DControllerScript.inVehicle)
                {
                    Handheld.Vibrate();
                    if (PControllerScript.DControllerScript.inVehicle)
                    {
                        Debug.Log("EXIT DELOREAN");
                        PControllerScript.DControllerScript.inVehicle = false;
                        martyMcFly.transform.position = new Vector3(theDeLorean.transform.position.x + 2, theDeLorean.transform.position.y + 2, 0);
                        PControllerScript.canMove = true;
                    }
                }
            }
        }
        if (Input.GetKey (KeyCode.D) || martyRight)
        {
            PControllerScript.isRight = true;
            PControllerScript.isLeft = false;
            PControllerScript.isUp = false;
            PControllerScript.isDown = false;
        }
        else if (Input.GetKey (KeyCode.A) || martyLeft)
        {
            PControllerScript.isLeft = true;
            PControllerScript.isRight = false;
            PControllerScript.isUp = false;
            PControllerScript.isDown = false;
        }
        else if (Input.GetKey (KeyCode.W) || martyUp)
        {
            PControllerScript.isUp = true;
            PControllerScript.isRight = false;
            PControllerScript.isLeft = false;
            PControllerScript.isDown = false;
        }
        else if (Input.GetKey (KeyCode.S) || martyDown)
        {
            PControllerScript.isDown = true;
            PControllerScript.isRight = false;
            PControllerScript.isLeft = false;
            PControllerScript.isUp = false;
        }
        else
        {
            PControllerScript.isRight = false;
            PControllerScript.isLeft = false;
            PControllerScript.isUp = false;
            PControllerScript.isDown = false;
        }
        if (DeLoreanLeft)
        {
            PControllerScript.DControllerScript.isLeft = true;
            PControllerScript.DControllerScript.isRight = false;
            PControllerScript.DControllerScript.isUp = false;
            PControllerScript.DControllerScript.isDown = false;
        }
        else if (DeLoreanRight)
        {
            PControllerScript.DControllerScript.isRight = true;
            PControllerScript.DControllerScript.isLeft = false;
            PControllerScript.DControllerScript.isUp = false;
            PControllerScript.DControllerScript.isDown = false;
        }
        else if (DeLoreanUp)
        {
            PControllerScript.DControllerScript.isUp = true;
            PControllerScript.DControllerScript.isLeft = false;
            PControllerScript.DControllerScript.isRight = false;
            PControllerScript.DControllerScript.isDown = false;
        }
        else if (DeLoreanDown)
        {
            PControllerScript.DControllerScript.isDown = true;
            PControllerScript.DControllerScript.isLeft = false;
            PControllerScript.DControllerScript.isRight = false;
            PControllerScript.DControllerScript.isUp = false;
        }
        else
        {
        }
    }
